solution_files_json.main.tf:
module "web_server" {
  source      = "./modules/server-config"
  server_name = "web"
  port        = 80
  environment = "production"
}

module "api_server" {
  source      = "./modules/server-config"
  server_name = "api"
  port        = 3000
  environment = "production"
}

solution_files_json.modules/server-config/main.tf:
resource "local_file" "config" {
  filename = "${var.server_name}-${var.environment}.conf"
  content  = <<-EOT
    server_name = ${var.server_name}
    port        = ${var.port}
    environment = ${var.environment}
  EOT
}

solution_files_json.modules/server-config/variables.tf:
variable "server_name" {
  type        = string
  description = "Name of the server"
}

variable "port" {
  type        = number
  description = "Port number"
}

variable "environment" {
  type        = string
  description = "Deployment environment"
  default     = "dev"
}

solution_files_json.modules/server-config/outputs.tf:
output "config_path" {
  value       = local_file.config.filename
  description = "Path to the generated config file"
}
